import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>الفافيكون ليس صورة واحدة، بل عائلة صور بأحجام مختلفة، كل منها يخدم مكانًا مختلفًا في المتصفح أو الجهاز. الأصغر 16 في 16 بكسل للتبويب، والأكبر 512 في 512 بكسل لشاشة ترحيب أندرويد.</p>\n<p>فهم أي حجم يذهب إلى أي مكان ينقذك من الفشلين الكلاسيكيين: أيقونة تبويب ضبابية وأيقونة شاشة رئيسية مبكسلة. يمر هذا الدليل على كل حجم في حزمة كاملة، من 16 إلى 512 بكسل، ويشرح ما يفعله كل منها.</p>\n<p>كل هذه الأحجام تخرج من رفع واحد في <a href=\"/ar/munshi-favicon/\">مولد الفافيكون</a>. لا تحتاج أبدًا إلى تصدير كل حجم يدويًا. لكن معرفة ما تحتويه الحزمة تساعدك على التحقق من عدم فقدان شيء وعلى تصميم علامة تعمل في كل مكان.</p>\n<h2 id=\"the-16-pixel-tab-icon\">أيقونة التبويب 16 بكسل</h2>\n<p>16 في 16 بكسل هو الحجم الذي وُلد به الفافيكون، وما زال الحجم الذي يراه معظم الناس أكثر. إنه في تبويب المتصفح بجانب عنوان الصفحة، وفي قوائم الإشارات وقوائم السجل.</p>\n<p>عند هذا الحجم تنجو فقط الأشكال الأقوى. حرف واحد أو رمز صلب أو شكل عالي التباين يُقرأ بوضوح. الخطوط الرفيعة تختفي والتدرجات تتسطح والنص الصغير يصبح غير مقروء. وعندما تراجع أيقونتك، انظر إلى معاينة 16 بكسل قبل أي شيء آخر.</p>\n<h2 id=\"the-32-pixel-retina-tab-icon\">أيقونة تبويب ريتينا 32 بكسل</h2>\n<p>32 في 32 بكسل هي نسخة ريتينا من أيقونة التبويب. الشاشات عالية الكثافة تحشر ضعف البكسلات الفيزيائية في المساحة نفسها، فتطلب المتصفحات هذا الحجم الأكبر.</p>\n<p>على شاشة عادية، تُصغَّر أيقونة 32 بكسل إلى 16 وتبدو مثل الملف الأصغر. وعلى شاشة ريتينا، تُعرض بكل حدتها بحواف تبدو محددة بدل ناعمة. وحاوي ICO يحفظ نسختي 16 و32 بكسل، فيختار المتصفح المناسبة للشاشة التي يعمل عليها.</p>\n<h2 id=\"the-48-pixel-shortcut-icon\">أيقونة الاختصار 48 بكسل</h2>\n<p>48 في 48 بكسل هو الحجم الذي يستخدمه ويندوز لاختصارات سطح المكتب والتثبيتات في شريط المهام. عندما يسحب شخص موقعك إلى سطح المكتب أو يثبته، تكون هذه الأيقونة هي التي يراها كل صباح.</p>\n<p>تظهر أيضًا في بعض مديري إشارات المتصفح وشريط عناوين المتصفحات القديمة. إنه حجم وسيط: كبير بما يكفي لعرض تفاصيل أكثر قليلًا من التبويب، وصغير بما يكفي ليبقى أيقونة. ويضم ملف ICO حجم 48 بكسل مع الأصغر، فتتلقى اختصارات سطح المكتب أيقونة مناسبة بدل ملف 16 بكسل ممدد.</p>\n<h2 id=\"the-64-and-96-pixel-sizes\">حجما 64 و96 بكسل</h2>\n<p>أيقونتا 64 و96 بكسل تغطيان السياقات الوسيطة: بلاطات إشارات أكبر وصفحات تبويب جديد في المتصفح وبعض واجهات الإضافات. إنها الأحجام التي تظهر عندما يعرض المتصفح أيقونتك أكبر من تبويب لكن أصغر من شاشة رئيسية.</p>\n<p>عند 64 بكسل، يمكن للشعار أن يحمل طابعًا أكثر قليلًا من 16. علامة بلونين أو رمز بسيط بشكل خلفية يُقرأ جيدًا. وعند 96 بكسل، تبدأ الأيقونة بالظهور كشعار صغير. وهذه الأحجام تعيش أيضًا داخل حاوي ICO، فلا تكلف شيئًا إضافيًا.</p>\n<h2 id=\"the-180-pixel-apple-touch-icon\">أيقونة Apple Touch 180 بكسل</h2>\n<p>180 في 180 بكسل هي أيقونة Apple Touch، وتُستخدم عندما يضيف مستخدم آيفون أو آيباد موقعك إلى الشاشة الرئيسية. إنه أول حجم تُعرض فيه أيقونتك كبيرة بما يكفي ليرى الناس تفاصيلها.</p>\n<p>تتجاهل Apple الشفافية في هذه الأيقونة وتملأ المناطق الشفافة بالأسود. شعار بخلفية شفافة يحصل على زوايا سوداء تبدو كخطأ، فالخلفية الصلبة هي الخيار الآمن. كما تطبق Apple قناع زوايا مدورة خاصًا بها على أيقونات الشاشة الرئيسية، فزوايا صورتك 180 بكسل مخفية خلف شكل النظام.</p>\n<h2 id=\"the-192-pixel-android-icon\">أيقونة أندرويد 192 بكسل</h2>\n<p>192 في 192 بكسل هي أيقونة الشاشة الرئيسية لأندرويد، المدرجة في بيان الويب. عندما يضيف مستخدم أندرويد موقعك إلى الشاشة الرئيسية، تكون هذه الأيقونة هي التي يراها.</p>\n<p>يطبق أندرويد قناعًا على الأيقونة حسب الجهاز والمشغل، فالمنطقة الآمنة مهمة. أبقِ العلامة متمركزة مع حشو حولها، لأن المشغل قد يقص الحواف في شكل دائري أو مربع مدور. وتُستخدم أيقونة 192 بكسل أيضًا لرسالة التثبيت ولموقعك في درج التطبيقات في بعض الأجهزة.</p>\n<h2 id=\"the-512-pixel-android-icon\">أيقونة أندرويد 512 بكسل</h2>\n<p>512 في 512 بكسل هو أكبر حجم في الحزمة، ويُستخدم لشاشة ترحيب أندرويد ورسالة التثبيت. عندما يفتح مستخدم تطبيق الويب المثبت لديك، تملأ هذه الأيقونة شاشة الترحيب.</p>\n<p>عند هذا الحجم، يظهر كل عيب في الصورة المصدر. شعار منخفض الدقة ممدد إلى 512 بكسل يبدو ناعمًا، وJPEG بآثار ضغط يعرضها دون تمويه. وابدأ بصورة مصدر لا تقل عن 512 بكسل، أو بـSVG، لتبدو الأيقونة الأكبر حادة مثل الأصغر. والصورة المتجهة مثالية هنا لأنها تتحجّم إلى 512 دون فقدان حدة.</p>\n<h2 id=\"how-the-ico-container-works\">كيف يعمل حاوي ICO</h2>\n<p>صيغة ICO حاوية تحفظ صورًا عدة بأحجام مختلفة في ملف واحد. ملف favicon.ico نموذجي يحتوي نسخ 16 و32 و48 وأحيانًا 64 بكسل، كل منها محفوظة كإطار منفصل.</p>\n<p>عندما يحتاج متصفح أيقونة، يفتح ملف ICO وينظر إلى الأحجام المتاحة ويختار الأقرب إلى ما يحتاجه. ولهذا يستطيع ملف واحد خدمة التبويب وقائمة الإشارات واختصار سطح المكتب. وملف ICO الذي ينتجه المولد ثنائي ICO حقيقي متعدد الإطارات، وهذا الفرق مهم لأن PNG معاد تسميته بامتداد ICO يخدع بعض المتصفحات ويفشل في أخرى.</p>\n<h2 id=\"which-size-does-what\">أي حجم يفعل ماذا: خريطة سريعة</h2>\n<p>أيقونة التبويب 16 بكسل، مع 32 لشاشات ريتينا. اختصارات سطح المكتب وتثبيتاته تستخدم 48 بكسل. بلاطات الإشارات الأكبر وصفحات التبويب الجديد تستخدم 64 و96 بكسل.</p>\n<p>الشاشة الرئيسية لـApple تستخدم 180 بكسل، وأندرويد يستخدم 192 للشاشة الرئيسية و512 لشاشة الترحيب ورسالة التثبيت. وكل حجم مسافة عرض مختلفة: أيقونة التبويب تُرى بنظرة بين تبويبات كثيرة، وأيقونة الشاشة الرئيسية تُرى بقصد بين تطبيقات، وأيقونة الترحيب تُرى بملء الشاشة.</p>\n<h2 id=\"designing-for-every-size\">كيف تصمم لكل الأحجام</h2>\n<p>صمم أولًا للحجم الأصغر. إذا قُرئت العلامة عند 16 بكسل، فستُقرأ في كل الأحجام الأكبر، لأن الأحجام الكبيرة تضيف مساحة وحدة فقط. وإذا احتاجت العلامة 180 بكسل لتُفهم، فستتفكك عند 16.</p>\n<p>استخدم شكلًا واحدًا قويًا ولونًا أو لونين وتباينًا قويًا. حرف أول واحد بلون علامة فوق خلفية صلبة هو تصميم الفافيكون الأكثر موثوقية. واختبر العلامة عند 16 و180 و512 بكسل قبل نشرها: هذه الأحجام الثلاثة تمثل التبويب والشاشة الرئيسية وشاشة الترحيب.</p>\n<h2 id=\"checking-your-pack\">كيف تراجع حزمتك</h2>\n<p>بعد التوليد، افتح ZIP وتأكد من وجود ملف ICO وPNG Apple Touch وPNG أندرويد 192 و512 بكسل والبيان. ملف مفقود يعني غالبًا تنزيلًا متقطعًا أو رفعًا غير مكتمل.</p>\n<p>ثبّت الحزمة على موقعك ثم راجع أيقونة التبويب وأيقونة الإشارات وأيقونة الشاشة الرئيسية على هاتف حقيقي. كل مراجعة تختبر حجمًا مختلفًا، ومعًا تغطي النطاق كله. وامسح ذاكرة المتصفح المؤقتة إذا استمر ظهور الأيقونة القديمة، واختبر في نافذة خاصة لترى ما يراه زائر جديد.</p>\n<h2 id=\"quick-reference\">مرجع سريع: أحجام الفافيكون في لمحة</h2>\n<p>تبويب: 16 بكسل، وريتينا 32. اختصار سطح مكتب: 48. بلاطات إشارات: 64 و96. شاشة Apple الرئيسية: 180. شاشة أندرويد الرئيسية: 192. ترحيب أندرويد وتثبيته: 512.</p>\n<p>صمم أولًا لـ16 بكسل، وابدأ بصورة مصدر لا تقل عن 512 بكسل أو SVG، وأعطِ أيقونة Apple خلفية صلبة. واختبر التبويب والإشارة والشاشة الرئيسية قبل النشر.</p>\n<p>للدليل الكامل، اقرأ <a href=\"/ar/blog/dalil-munshi-favicon/\">مولد الفافيكون: الدليل الكامل</a>، وللخطوات اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-favicon/\">كيف تنشئ فافيكون</a>. وولّد حزمتك مع <a href=\"/ar/munshi-favicon/\">مولد الفافيكون</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أصغر حجم فافيكون أحتاجه؟","answer":"16 في 16 بكسل هو أصغر حجم، ويُستخدم لتبويب المتصفح. وهو أيضًا أصعب تصميم، لأن الأشكال الأقوى فقط تنجو عند ذلك الحجم. وراجع دائمًا معاينة 16 بكسل قبل أي حجم آخر."},{"question":"لماذا أحتاج إلى أيقونة 512 في 512 لفافيكون تبويب صغير؟","answer":"أيقونة 512 بكسل ليست للتبويب، فأندرويد يستخدمها لشاشة الترحيب ورسالة التثبيت، حيث تُعرض الأيقونة كبيرة. حزمة دونها تعرض أيقونة ممددة أو مفقودة على أندرويد."},{"question":"هل يكفي فافيكون PNG أم أحتاج إلى ملف ICO؟","answer":"PNG يعمل في المتصفحات الحديثة، لكن ملف ICO ما زال الافتراضي: المتصفحات تطلب favicon.ico في جذر الموقع حتى دون مقتطف، وحاوي ICO يحفظ أحجامًا عدة في ملف واحد. والحزمة الكاملة تضم كليهما."},{"question":"أي حجم يجب أن يكون شعار المصدر لفافيكون؟","answer":"512 في 512 بكسل على الأقل، أو SVG دون دقة ثابتة. أكبر أيقونة في الحزمة 512 بكسل، فصورة أصغر تُمدد وتبدو ناعمة. صورة كبيرة أو ملف متجه يبقي كل الأحجام حادة."},{"question":"لماذا تحتاج أيقونة Apple Touch إلى خلفية صلبة؟","answer":"تملأ Apple المناطق الشفافة في أيقونة الشاشة الرئيسية بالأسود، ما يبدو كخطأ عرض. خلفية صلبة بلون علامتك تتجنب الزوايا السوداء تمامًا وتجعل الأيقونة تبدو مقصودة على الشاشة الرئيسية."},{"question":"هل كل المتصفحات تستخدم أحجام فافيكون نفسها؟","answer":"في الغالب لكن ليس تمامًا. كل المتصفحات تستخدم 16 و32 بكسل للتبويبات، بينما لكل من Apple وأندرويد أحجامهما الخاصة للشاشة الرئيسية. والحزمة الكاملة تغطي الجميع."}];
